// Part 3, Timber frame: the first-floor and loft storeys on both faces and both sides, the jetty brackets, the head plates
// (y17 and the cornice y23), the hoist beams and hoods, and the gable frames. The north face is drawn; the south face is
// its mirror (z -> 37 - z, facings flipped). Writes only into air: earlier parts' cells are left alone.
import { FRAME_LOG, INFILL, NORTH_FIRST_Z, NORTH_LOFT_Z, mirrorZ, frameBay, beam, jettyBracket, gableFrame, hoistBeam, hoistHood } from "../vocab.mjs";

// first floor: y13..17 (sill y12 is the floor slab, head plate y17); loft: y19..22 (sill y18, head plate y23)
const FIRST = { y0: 13, y1: 17 };
const LOFT = { y0: 19, y1: 22 };

// front bays (plan FACADES): posts at x 2,5,9,10,13,17,21,25,29,32,33,37,40; door bays keep x 11..12 and 30..31 open
const BAYS = [
  [2, 5, "mann"], [5, 9, "window"], [10, 13, "door"], [13, 17, "brace"], [17, 21, "window"],
  [21, 25, "window"], [25, 29, "brace"], [29, 32, "door"], [33, 37, "window"], [37, 40, "brace"],
];
const POSTS = [2, 5, 9, 10, 13, 17, 21, 25, 29, 32, 33, 37, 40];
const DOOR_COLS = [[11, 12], [30, 31]];

// side walls (x 2 and x 40): posts every 4 on z, one window (air) per third bay at z 7, 19, 31
const SIDE_POSTS = [5, 9, 13, 17, 21, 25, 29];
const SIDE_WINDOWS = [7, 19, 31];
const SIDE_WINDOW_ROWS = { first: [14, 15], loft: [20, 21] };

// the first-floor and loft storey frames on one face, at the front planes zF (first) and zL (loft)
function storeyFront(g, zF, zL) {
  for (const [x0, x1, fill] of BAYS) {
    frameBay(g, x0, x1, FIRST.y0, FIRST.y1, zF, { fill });
    frameBay(g, x0, x1, LOFT.y0, LOFT.y1, zL, { fill });
  }
  // lintels over the loading doors (the doors take y13..14 with the transom on 15; loft doors 19..20, transom 21)
  for (const [xa, xb] of DOOR_COLS) {
    beam(g, xa, xb, 16, zF, "x");
    beam(g, xa, xb, 22, zL, "x");
  }
}

// head plates: the first-floor head plate (y17) and the loft's cornice (y23) run the whole front
function headPlates(g, zF, zL) {
  beam(g, 2, 40, 17, zF, "x");
  beam(g, 2, 40, 23, zL, "x");
}

// jetty brackets: one under every first-floor post (y11, out of the sill at y12) and one under every loft post (y17)
function brackets(g, zF, zL, facing) {
  for (const x of POSTS) {
    jettyBracket(g, x, 11, zF, facing);
    jettyBracket(g, x, 17, zL, facing);
  }
}

// side walls: calcite between posts, the window cells left open for the window units (P5)
function sideWalls(g) {
  const storeys = [
    { y0: FIRST.y0, y1: FIRST.y1, zs: range(5, 32), win: SIDE_WINDOW_ROWS.first },
    { y0: LOFT.y0, y1: LOFT.y1, zs: range(4, 33), win: SIDE_WINDOW_ROWS.loft },
  ];
  for (const x of [2, 40]) {
    for (const { y0, y1, zs, win } of storeys) {
      for (const z of zs) {
        for (let y = y0; y <= y1; y++) {
          if (SIDE_WINDOWS.includes(z) && y >= win[0] && y <= win[1]) continue; // window opening
          if (SIDE_POSTS.includes(z)) g.set(x, y, z, FRAME_LOG, { axis: "y" });
          else g.set(x, y, z, INFILL);
        }
      }
    }
  }
}

function range(a, b) {
  const out = [];
  for (let i = a; i <= b; i++) out.push(i);
  return out;
}

export function build(g) {
  // hoist beams and hoods first, so the beam's cells at the gable plane are kept
  for (const x of [11, 30]) {
    hoistBeam(g, x, 0, 3, "north");
    hoistBeam(g, x, 34, 37, "south");
  }
  for (const x0 of [10, 29]) {
    hoistHood(g, x0, 1, "north");
    hoistHood(g, x0, 34, "south");
  }

  // north face (front planes z 4 first floor, z 3 loft); the south face is the mirror
  const zF = NORTH_FIRST_Z, zL = NORTH_LOFT_Z;
  storeyFront(g, zF, zL);
  headPlates(g, zF, zL);
  brackets(g, zF, zL, "south"); // the wall lies to the south of a north bracket

  // south face: mirror z, facings flipped
  const sF = mirrorZ(zF), sL = mirrorZ(zL);
  storeyFront(g, sF, sL);
  headPlates(g, sF, sL);
  brackets(g, sF, sL, "north");

  sideWalls(g);

  // gable frames: the wall triangles at the roof's gable planes (z 3 and z 34), king post pairs at x 11..12 and 30..31
  gableFrame(g, 2, 21, zL, "north");
  gableFrame(g, 21, 40, zL, "north");
  gableFrame(g, 2, 21, sL, "south");
  gableFrame(g, 21, 40, sL, "south");
}
// Part 5, Shopfronts (six Folio businesses, both faces): fascia names, piers with log-end panels, awnings in each
// business's wood, and hanging signs on the piers (plan FACADES, item 4 of the parts). Every helper writes only into air,
// so the socket boxes, wall lines and clear zones stay untouched. North = z 5 (fascia), south = z 32 (mirror of 5).
import { fasciaBoard, pierPanel, awning, hangSign } from "../vocab.mjs";

// the palette lists four standing banners (white, black, brown, orange) and wall hanging signs, not the wall banners or every
// dye the vocabulary writes: a wall banner becomes the standing banner of its dye, turned to face the same way (standing
// rotation 0 faces south, 4 west, 8 north, 12 east), a banner in a dye off the list takes the nearest listed one, and a
// wall sign becomes the hanging sign of its wood
const BANNER_DYE = { light_gray: "white", red: "brown" };
const STANDING_ROTATION = { south: "0", west: "4", north: "8", east: "12" };

const withNbt = (nbt, key, value) => nbt && { ...nbt, value: { ...nbt.value, [key]: value } };

// the block a vocabulary write lands as, and its block entity (sign text, banner patterns) to match
function paletteBlock(block, state, nbt) {
  const sign = /^((?:minecraft:)?)(\w+)_wall_sign$/.exec(block);
  if (sign) return { block: `${sign[1]}${sign[2]}_wall_hanging_sign`, state, nbt: withNbt(nbt, "id", { type: "string", value: "minecraft:hanging_sign" }) };
  const banner = /^((?:minecraft:)?)(\w+)_wall_banner$/.exec(block);
  if (!banner) return { block, state, nbt };
  const old = banner[2], dye = BANNER_DYE[old] ?? old, pats = nbt?.value?.patterns;
  const standing = { rotation: STANDING_ROTATION[state.facing] };
  if (dye === old) return { block: `${banner[1]}${dye}_banner`, state: standing, nbt };
  const contrast = dye === "white" ? "black" : "white";
  // the cloth's own colour (the border) moves to the new cloth; a letter that now shares the cloth's dye would vanish, so it takes the contrast
  const fixed = (pats?.value?.value ?? []).map((p) => {
    if (p.color.value === old) return { ...p, color: { type: "string", value: dye } };
    if (p.color.value === dye) return { ...p, color: { type: "string", value: contrast } };
    return p;
  });
  return { block: `${banner[1]}${dye}_banner`, state: standing, nbt: pats ? withNbt(nbt, "patterns", { ...pats, value: { ...pats.value, value: fixed } }) : nbt };
}

// the grid as the street sees it: every write goes through paletteBlock first
function paletteView(g) {
  const view = new Proxy(g, {
    get(target, prop) {
      if (prop === "set") return (x, y, z, block, state, nbt) => { const s = paletteBlock(block, state, nbt); target.set(x, y, z, s.block, s.state, s.nbt); return view; };
      const v = Reflect.get(target, prop);
      return typeof v === "function" ? v.bind(target) : v;
    },
  });
  return view;
}

// one business per frontage: [name on the fascia, wood, x0, x1]
const NORTH = [
  ["BIRCH", "birch", 10, 16],
  ["SPRUCE", "spruce", 18, 24],
  ["OAK", "oak", 26, 32],
];
const SOUTH = [
  ["JUNGLE", "jungle", 10, 16],
  ["ACACIA", "acacia", 18, 24],
  ["DK OAK", "dark_oak", 26, 32],
];

// piers on the wall lines, with the business whose panel and sign hang on each (plan FACADES: hanging signs)
const NORTH_PIERS = [[9, "birch"], [17, "spruce"], [25, "oak"], [33, "oak"]];
const SOUTH_PIERS = [[9, "jungle"], [17, "jungle"], [25, "acacia"], [33, "dark_oak"]];
const NORTH_SIGNS = [[9, "birch", "BIRCH"], [17, "spruce", "SPRUCE"], [25, "oak", "OAK"]];
const SOUTH_SIGNS = [[17, "jungle", "JUNGLE"], [25, "acacia", "ACACIA"], [33, "dark_oak", "DK OAK"]];

function street(g, face, shops, piers, signs) {
  const out = { placed: 0, skipped: 0 };
  // fascia boards with the names, one per business
  for (const [name, wood, x0, x1] of shops) {
    const r = fasciaBoard(g, x0, x1, face, wood, name);
    out.placed += r.placed; out.skipped += r.skipped;
  }
  // awnings: each business's wood, over its 7-wide frontage
  for (const [, wood, x0, x1] of shops) awning(g, x0, x1, face, wood);
  // piers with the log-end product panels
  for (const [x, wood] of piers) pierPanel(g, x, face, wood);
  // hanging signs on the piers, from the jetty brackets
  for (const [x, wood, name] of signs) hangSign(g, x, face, wood, name);
  return out;
}

export function build(g) {
  const p = paletteView(g);
  const north = street(p, "north", NORTH, NORTH_PIERS, NORTH_SIGNS);
  const south = street(p, "south", SOUTH, SOUTH_PIERS, SOUTH_SIGNS);
  return { placed: north.placed + south.placed, skipped: north.skipped + south.skipped };
}
// The shared vocabulary: written by the workflow from vocab/ (base constants + helper shares)
export * from "./vocab/base.mjs";
export * from "./vocab/h1.mjs";
export * from "./vocab/h2.mjs";
export * from "./vocab/h3.mjs";
