  const lamp = [x + 1, y, z + out];
  const hung = g.isAir(x + 1, y + 1, z + out) ? { placed: 0, skipped: 1 } : place(g, box, [[...lamp, "lantern", { hanging: "true" }]]);
  return { placed: sign.cells + hung.placed, skipped: sign.skipped + hung.skipped, box };
