35	export function layoutText(text, font = "wide") {
36	  const cells = [];
37	  let x = 0;
38	  for (const ch of text) {
39	    const g = glyph(ch, font);
40	    g.forEach((row, r) => [...row].forEach((c, k) => { if (c === "1") cells.push({ x: x + k, y: 4 - r }); }));
41	    x += g[0].length + 1;
42	  }
43	  return { cells, width: Math.max(0, x - 1) };
44	}
45	const wrap2 = (text) => {                                        // the most balanced split into two lines at a space
46	  const words = text.split(" ");
47	  if (words.length < 2) return null;
48	  let best = null;
49	  for (let k = 1; k < words.length; k++) { const a = words.slice(0, k).join(" "), b = words.slice(k).join(" "); const s = Math.max(a.length, b.length); if (!best || s < best.s) best = { s, lines: [a, b] }; }
