74	/** Banner patterns for a character: letter dye on base dye; "*" layers are drawn in the base dye (to cut back), and a
75	 *  base-coloured border closes every letter so neighbouring banners read as separate characters. */
76	export function bannerLetter(ch, letterDye, baseDye) {
77	  const r = BANNER_LETTER[String(ch).toUpperCase()];
78	  if (!r) return null;
79	  return [...r.map((p) => (p.endsWith("*") ? [p.slice(0, -1), baseDye] : [p, letterDye])), ["border", baseDye]];
80	}
81	const DYE_RGB = { white: [234, 236, 237], orange: [241, 118, 20], magenta: [190, 69, 180], light_blue: [58, 175, 217], yellow: [249, 198, 40], lime: [112, 185, 26],
82	  pink: [238, 141, 172], gray: [63, 68, 72], light_gray: [142, 142, 135], cyan: [21, 138, 145], purple: [122, 42, 173], blue: [53, 57, 157], brown: [114, 72, 41],
83	  green: [85, 110, 28], red: [161, 39, 35], black: [21, 21, 26] };
84	/** The dye closest in colour to a block (banner cloth that matches a board or a letter material). */
85	export function dyeOf(blockName) {
86	  const c = colourOf(blockName);
87	  if (!c) return "white";
88	  return Object.entries(DYE_RGB).map(([d, v]) => [d, v.reduce((s, x, i) => s + (x - c[i]) ** 2, 0)]).sort((a, b) => a[1] - b[1])[0][0];
