93	  const side = (ls) => ({ messages: tg.list("string", [0, 1, 2, 3].map((i) => msg(ls[i]))), color: tg.string(color), has_glowing_text: tg.byte(glow ? 1 : 0) });
94	  return tg.compound({ id: tg.string("minecraft:sign"), is_waxed: tg.byte(0), front_text: tg.compound(side(lines)), back_text: tg.compound(side([])) });
95	};
96	/** Split text over n signs, whole words per sign where possible (up to 4 lines of 15 characters each). */
97	function signChunks(text, n) {
98	  const words = text.split(/\s+/).filter(Boolean), out = Array.from({ length: n }, () => []);
99	  if (words.length <= n) { const off = Math.floor((n - words.length) / 2); words.forEach((w, i) => out[off + i].push(w)); }
100	  else { const per = Math.ceil(words.length / n); words.forEach((w, i) => out[Math.min(n - 1, Math.floor(i / per))].push(w)); }
101	  return out.map((ws) => { const lines = []; for (const w of ws) { const l = lines.at(-1); if (l != null && (l + " " + w).length <= 15) lines[lines.length - 1] = l + " " + w; else lines.push(w.slice(0, 15)); } return lines.slice(0, 4); });
102	}
103	
104	// ---- material choice ------------------------------------------------------------------------------------------------
105	const LIGHT_LETTERS = ["gold_block", "smooth_quartz", "white_concrete", "yellow_concrete"], DARK_LETTERS = ["black_concrete", "polished_blackstone", "dark_oak_planks", "deepslate_tiles"];
106	/** Letters that read on a board: the requested block if legible, else the best of the light (dark board) or dark set. */
107	export function chooseLetter(board, requested, notes = []) {
108	  if (requested && legible(requested, board)) return requested;
109	  const dark = (lumOf(board) ?? 128) < 110, pool = dark ? LIGHT_LETTERS : DARK_LETTERS;
110	  const pick = pool.find((b) => legible(b, board)) ?? pool[0];
111	  if (requested) notes.push(`plaque: ${requested} letters would not read on ${board} (contrast under 35%): used ${pick}`);
112	  return pick;
113	}
114	
115	/**
116	 * A plaque: lettering centred in a band, the letter style chosen by the space. Styles tried in order (style: "auto"):
117	 *   block    5-row font, wide then narrow glyphs, one line then two, on a board with a 1-cell margin and a frame ring
118	 *            (frame and margin are dropped first when the band is short); a drip cap of stairs over the frame
119	 *   banner   one banner letter per character hung on a 2-row board (bands 2-4 rows tall, or too narrow for blocks)
120	 *   sign     wall signs across a 1-row band
121	 * material: the board (null keeps the wall as the board: block letters set into it, banners hung on it, nothing
122	 * repainted); letter: the letter block (checked for contrast); frame:
123	 * the ring block (null: none). relief "raised" puts the letters one block proud of the board instead of flush.
124	 * plan.info.style tells which style was used.
125	 */
126	export function plaquePlan(text, { at, face, width, height, letter, material = "dark_oak_planks", frame: frameBlock = "stripped_spruce_wood", style = "auto", relief = "flush", cap = true, look = LOOK_NONE, wall, dataVersion = 4189 } = {}) {
127	  const F = frame(face, at), writes = [], notes = [], T = String(text ?? "").toUpperCase().replace(/\s+/g, " ").trim();
128	  if (!T) return { writes, notes: ["plaque: no text (write the words in quotes)"], info: { style: "none" } };
129	  const W = width, H = height;
130	  // no board (material: null): the letters go on the wall as it stands, so the wall's own block is the ground they
131	  // must read against (the plan reads it from the band's centre when the caller didn't name it)
132	  const seen = look.block(F.p(Math.floor((W - 1) / 2), Math.floor((H - 1) / 2)));
133	  const board = material || wall || (seen && seen !== "air" ? seen : "stone_bricks");
134	  const tryBlock = () => {
135	    for (const lines of [[T], wrap2(T)].filter(Boolean)) for (const [pad, fr] of [[1, 1], [1, 0], [0, 0]]) for (const font of ["wide", "narrow"]) {
136	      const lw = Math.max(...lines.map((l) => textWidth(l, font))), th = lines.length * 5 + (lines.length - 1);
137	      {
138	        if (fr && !frameBlock) continue;
139	        if (!material && pad && !fr) continue;                             // no board and no frame: margin is meaningless
140	        const bw = lw + 2 * pad + 2 * fr, bh = th + 2 * pad + 2 * fr;
141	        if (bw <= W && bh <= H) return { lines, font, pad, fr, bw, bh, lw, th };
142	      }
143	    }
144	    return null;
145	  };
146	  const S = style === "auto" || style === "block" ? tryBlock() : null;
147	  if (S) {
148	    const ink = chooseLetter(board, letter, notes);
149	    const u0 = Math.floor((W - S.bw) / 2), v0 = Math.floor((H - S.bh) / 2);
150	    const ink2 = new Set();
151	    S.lines.forEach((line, li) => {
152	      const L = layoutText(line, S.font), x0 = u0 + S.fr + S.pad + Math.floor((S.lw - L.width) / 2);
153	      const y0 = v0 + S.fr + S.pad + (S.lines.length - 1 - li) * 6;
154	      for (const c of L.cells) ink2.add(`${x0 + c.x},${y0 + c.y}`);
155	    });
156	    for (let u = u0; u < u0 + S.bw; u++) for (let v = v0; v < v0 + S.bh; v++) {
157	      const ring = S.fr && (u === u0 || v === v0 || u === u0 + S.bw - 1 || v === v0 + S.bh - 1);
158	      if (ring) { writes.push(block(F.p(u, v), frameBlock, "recolor", /_(log|wood)$/.test(frameBlock) ? { state: { axis: u === u0 || u === u0 + S.bw - 1 ? "y" : F.right[0] ? "x" : "z" } } : {})); continue; }
159	      const isInk = ink2.has(`${u},${v}`);
160	      if (isInk && relief === "raised") { if (material) writes.push(block(F.p(u, v), material, "recolor")); writes.push(block(F.p(u, v, 1), ink, "air")); }
161	      else if (isInk) writes.push(block(F.p(u, v), ink, "recolor"));
162	      else if (material) writes.push(block(F.p(u, v), material, "recolor"));
163	    }
164	    if (cap && S.fr) for (let u = u0; u < u0 + S.bw; u++) writes.push(stair(F.p(u, v0 + S.bh - 1, 1), frameMat(frameBlock), F.outName, "top", "soft"));
165	    return { writes, notes, info: { style: "block", font: S.font, lines: S.lines, letter: ink, board: { u0, v0, w: S.bw, h: S.bh } } };
166	  }
167	  const chars = [...T];
168	  if ((style === "auto" || style === "banner") && H >= 2 && W >= chars.length) {
169	    const ink = chooseLetter(board, letter, notes), baseDye = dyeOf(board) === dyeOf(ink) ? ((lumOf(ink) ?? 128) > 110 ? "black" : "white") : dyeOf(board);
170	    let inkDye = dyeOf(ink);
171	    if (inkDye === baseDye) inkDye = baseDye === "black" ? "white" : "black";
172	    const bw = Math.min(W, chars.length + 2), u0 = Math.floor((W - bw) / 2), v0 = Math.floor((H - 2) / 2), x0 = u0 + Math.floor((bw - chars.length) / 2);
173	    // a board only when one is asked for: with material null the banners hang on the wall's own blocks, untouched
174	    if (material) for (let u = u0; u < u0 + bw; u++) for (let v = v0; v < v0 + 2; v++) writes.push(block(F.p(u, v), board, "recolor"));
175	    chars.forEach((ch, i) => {
176	      const pats = bannerLetter(ch, inkDye, baseDye);
177	      if (!pats) return;                                                  // a space: the board shows
178	      writes.push(block(F.p(x0 + i, v0 + 1, 1), `${baseDye}_wall_banner`, "rail", { state: { facing: F.outName }, nbt: bannerNbt(pats), support: F.p(x0 + i, v0 + 1) }));
179	    });
180	    return { writes, notes, info: { style: "banner", dyes: [inkDye, baseDye] } };
181	  }
182	  if (style === "sign" && H >= 2 && W >= chars.length) notes.push(`plaque: "${T}" was asked for as wall signs, which read only up close; style "banner" (or "auto") sets one banner letter per character here, on the wall as it is when material is null`);
183	  const n = Math.max(1, Math.min(W, Math.ceil(T.length / 12))), chunks = signChunks(T, n), u0 = Math.floor((W - n) / 2), wood = /^(oak|spruce|birch|jungle|acacia|dark_oak|mangrove|cherry|bamboo|crimson|warped|pale_oak)_planks$/.exec(board)?.[1] ?? "dark_oak";
184	  chunks.forEach((lines, i) => { if (lines.length) writes.push(block(F.p(u0 + i, Math.floor((H - 1) / 2), 1), `${wood}_wall_sign`, "rail", { state: { facing: F.outName, waterlogged: "false" }, nbt: signNbt(lines, { dataVersion, color: (lumOf(`${wood}_planks`) ?? 100) < 90 ? "white" : "black" }), support: F.p(u0 + i, Math.floor((H - 1) / 2)) })); });
185	  if (style !== "sign") notes.push(`plaque: the band (${W}x${H}) is too small for block or banner letters; used wall signs (give it 7+ rows for block letters, 2 for banners)`);
186	  return { writes, notes, info: { style: "sign" } };
187	}
188	/** The stairs material behind a frame block (logs and wood have no stairs: their planks). */
189	const frameMat = (b) => { const m = /^(?:stripped_)?(.+?)_(log|wood)$/.exec(b); return m ? `${m[1]}_planks` : b; };
190	
191	/**
192	 * A shop sign that reads at street distance.
193	 *   wall     a board (width x height of planks) one out from the wall, a slab cap on top, upside-down stair brackets
194	 *            under its ends, and the text on wall signs in front of it (whole words per sign)
195	 *   hanging  a blade sign at right angles to the wall: a fence arm out from the wall with a knee brace, the board hung
196	 *            under it on chains (or right under the arm when there is no room), text on both faces
197	 * at: the wall cell the sign centres on (wall: the board's bottom-centre; hanging: where the arm meets the wall).
198	 */
199	export function signboardPlan(text, { at, face, mode = "wall", width, height = 2, wood = "spruce", board, bracket, chains = true, look = LOOK_NONE, dataVersion = 4189 } = {}) {
200	  const F = frame(face, at), writes = [], notes = [], T = String(text ?? "").trim();
201	  const planks = board || `${wood}_planks`, fence = bracket || `${wood}_fence`, ink = (lumOf(planks) ?? 100) < 90 ? "white" : "black";
202	  const signAt = (p, facing, lines, support) => writes.push(block(p, `${wood}_wall_sign`, "rail", { state: { facing, waterlogged: "false" }, nbt: signNbt(lines, { dataVersion, color: ink }), support }));
203	  const chain = dataVersion >= 4554 ? "iron_chain" : "chain";
204	  if (mode === "hanging" || mode === "blade") {
205	    const w = width ?? 2, h = Math.max(1, height), gap = chains && look.air(F.p(0, -h - 1, 2)) ? 1 : 0;
206	    for (let d = 1; d <= w + 1; d++) writes.push(block(F.p(0, 0, d), fence, "rail", { state: connState(fence, [F.inName, ...(d <= w ? [F.outName] : [])]), ...(d === 1 ? { support: F.p(0, 0) } : {}) }));
207	    writes.push(stair(F.p(0, -1, 1), frameMat(planks), F.outName, "top", "rail", { support: F.p(0, -1) }));
208	    const top = -1 - gap;
209	    if (gap) for (const d of [2, w + 1]) writes.push(block(F.p(0, -1, d), chain, "rail", { state: { axis: "y", waterlogged: "false" } }));
210	    const chunks = signChunks(T, w);
211	    for (let k = 0; k < w; k++) for (let v = top; v > top - h; v--) {
212	      const p = F.p(0, v, 2 + k);
213	      writes.push(block(p, planks, "air"));
214	      if (v === top - Math.floor((h - 1) / 2)) {                           // text at mid-board, both faces
215	        const lines = chunks[k]; if (!lines.length) continue;
216	        signAt(F.p(1, v, 2 + k), F.rightName, lines, p); signAt(F.p(-1, v, 2 + k), F.leftName, lines, p);
217	      }
218	    }
219	    return { writes, notes, info: { mode: "hanging", reach: w + 1 } };
220	  }
221	  const w = width ?? Math.max(3, Math.min(7, Math.ceil(T.length / 5))), h = Math.max(1, height), u0 = -Math.floor((w - 1) / 2);
222	  for (let u = u0; u < u0 + w; u++) {
223	    for (let v = 0; v < h; v++) writes.push(block(F.p(u, v, 1), planks, "air", { support: F.p(u, v) }));
224	    writes.push(slab(F.p(u, h, 1), frameMat(planks), "bottom", "air"));
225	  }
226	  for (const u of [u0, u0 + w - 1]) writes.push(stair(F.p(u, -1, 1), frameMat(planks), F.outName, "top", "rail", { support: F.p(u, -1) }));
227	  const chunks = signChunks(T, w), row = h - 1;
228	  chunks.forEach((lines, i) => { if (lines.length) signAt(F.p(u0 + i, row, 2), F.outName, lines, F.p(u0 + i, row, 1)); });
229	  return { writes, notes, info: { mode: "wall", width: w } };
230	}
231	
232	/**
233	 * Bunting: a line of wall banners along a row (under an eave), colours alternating, one every `every` cells. Each
234	 * banner needs wall behind it and air for its cloth (its own cell and the one below); none hang over glass.
235	 * pattern "pennant" (default) cuts each cloth to a point with the base dye of its neighbour; "plain" is flat colour.
236	 */
237	export function buntingPlan({ from, to, face, colors = ["red", "white", "blue"], every = 2, pattern = "pennant", look = LOOK_NONE } = {}) {
238	  const F = frame(face, from), writes = [], notes = [];
239	  const dx = to[0] - from[0], dz = to[2] - from[2], n = Math.abs(F.right[0] ? dx : dz), sgn = Math.sign(F.right[0] ? dx * F.right[0] : dz * F.right[2]) || 1;
240	  if (to[1] !== from[1]) notes.push("bunting: from and to should be on one row (used from's row)");
241	  let k = 0;
242	  for (let i = 0; i <= n; i += Math.max(1, every)) {
243	    const u = i * sgn, cell = F.p(u, 0, 1), below = F.p(u, -1, 1), behindBelow = F.p(u, -1);
244	    if (!look.air(cell) || !look.air(below) || /glass|_pane$|_door$/.test(look.block(behindBelow)) || look.air(F.p(u, 0))) continue;
245	    const c = colors[k % colors.length], next = colors[(k + 1) % colors.length]; k++;
246	    const pats = pattern === "plain" ? [] : [["triangles_bottom", next === c ? "white" : next], ["stripe_top", next === c ? "white" : next]];
247	    writes.push(block(cell, `${c}_wall_banner`, "rail", { state: { facing: F.outName }, nbt: bannerNbt(pats), support: F.p(u, 0) }));
248	  }
249	  if (!writes.length) notes.push("bunting: no room (each banner needs wall behind it and two cells of air in front, clear of windows)");
250	  return { writes, notes, info: { banners: writes.length } };
251	}
